function decorativeEffect(effect){return effect.type==='spark'||effect.type==='smoke'||effect.type==='scorch'}
function pushEffect(effect){
  if(effect.type==='order')state.fx=state.fx.filter(e=>e.type!=='order');
  if(state.fx.length>=MAX_EFFECTS){
    let disposable=state.fx.findIndex(decorativeEffect);
    if(disposable>=0)state.fx.splice(disposable,1);
    else if(decorativeEffect(effect))return;
    else state.fx.shift(); // Critical feedback alone overloads: retain the existing oldest-first policy.
  }
  state.fx.push(effect);
}
// Cosmetic-only battlefield effects: fixed-angle sparks never consume the gameplay RNG.
// All effects share the 256-slot bound; only new decoration yields to existing feedback.
// Unknown types default to feedback. Natural expiry still belongs to the fx lifetime update.
function spawnImpactSparks(x,y,radius,seed,count){
  for(let i=0;i<count;i++){
    let angle=i*2.399963+seed*.73,reach=radius*(.6+(i%4)*.2),life=.32+(i%3)*.12;
    pushEffect({type:'spark',x,y,dx:Math.cos(angle)*reach,dy:Math.sin(angle)*reach-radius*.3,gravity:radius*.42,size:1.5+(i%3)*.55,t:life,max:life});
  }
}
function spawnDestructionEffects(target){
  let large=!defs[target.type].speed,radius=Math.max(25,target.r*(large?1.9:2.2));
  pushEffect({type:'boom',x:target.x,y:target.y,radius,t:.85,max:.85});
  spawnImpactSparks(target.x,target.y,radius*1.5,target.id,large?10:7);
  for(let i=0;i<(large?5:3);i++){
    let angle=i*2.399963+target.id*.6,life=2.3+i*.37;
    pushEffect({type:'smoke',x:target.x+Math.cos(angle)*radius*.2,y:target.y+Math.sin(angle)*radius*.13,dx:Math.cos(angle)*radius*.48,dy:-radius*(1.2+(i%3)*.24),radius:radius*(.4+(i%3)*.1),seed:i,t:life,max:life});
  }
  // A single ground decal also contains a few metallic wreck fragments. It is
  // transient, has no collision/selection footprint, and is never saved.
  pushEffect({type:'scorch',x:target.x,y:target.y,radius:radius*.83,seed:target.id,t:30,max:30});
}

// Blast marks are a ground layer: tank bodies, health bars and cursor indicators
// stay readable above them. Scorch marks expire through the normal fx tick.
function drawBattleScars(){
  ctx.save();
  for(let f of state.fx){
    if(f.type!=='scorch')continue;
    let fade=Math.min(1,f.t/4),r=f.radius,twist=f.seed*.13;
    ctx.globalAlpha=.72*fade;
    ctx.fillStyle='#131b19';
    ctx.beginPath();ctx.ellipse(f.x,f.y,r,r*.64,twist,0,Math.PI*2);ctx.fill();
    ctx.globalAlpha=.36*fade;
    ctx.strokeStyle='#b47749';ctx.lineWidth=2;
    ctx.beginPath();ctx.ellipse(f.x,f.y,r*.83,r*.53,twist,0,Math.PI*2);ctx.stroke();
    ctx.globalAlpha=.72*fade;
    ctx.fillStyle='#232724';
    ctx.beginPath();ctx.ellipse(f.x,f.y,r*.54,r*.34,twist,0,Math.PI*2);ctx.fill();
    for(let i=0;i<5;i++){
      let angle=f.seed*.79+i*2.399963,x=f.x+Math.cos(angle)*r*.54,y=f.y+Math.sin(angle)*r*.37;
      ctx.fillStyle=i%2?'#66645b':'#414b48';
      ctx.beginPath();ctx.moveTo(x,y);
      ctx.lineTo(x+Math.cos(angle+.32)*r*.2,y+Math.sin(angle+.32)*r*.13);
      ctx.lineTo(x+Math.cos(angle+1.9)*r*.12,y+Math.sin(angle+1.9)*r*.1);
      ctx.closePath();ctx.fill();
    }
    if(f.t>24){
      let glow=(f.t-24)/6*(.82+.18*Math.sin((30-f.t)*11+f.seed));
      ctx.globalAlpha=.83*glow;
      circle(f.x-r*.15,f.y+r*.07,Math.max(1.6,r*.09),'#ec8a40');
      circle(f.x+r*.19,f.y-r*.1,Math.max(1,r*.055),'#ffd184');
    }
  }
  ctx.restore();
}
function drawBattleEffect(f){
  if(f.type==='scorch')return;
  let remain=Math.max(0,Math.min(1,f.t/f.max)),p=1-remain;
  ctx.save();ctx.globalAlpha=remain;
  if(f.type==='order'){
    ctx.strokeStyle='#b9f5d2';ctx.lineWidth=2;ctx.beginPath();ctx.arc(f.x,f.y,8+p*25,0,Math.PI*2);ctx.stroke();
    rect(f.x-2,f.y-2,4,4,'#e3ffea');
    ctx.beginPath();ctx.moveTo(f.x-7,f.y);ctx.lineTo(f.x-4,f.y);ctx.moveTo(f.x+4,f.y);ctx.lineTo(f.x+7,f.y);ctx.moveTo(f.x,f.y-7);ctx.lineTo(f.x,f.y-4);ctx.moveTo(f.x,f.y+4);ctx.lineTo(f.x,f.y+7);ctx.stroke();
  }else if(f.type==='blast'){
    ctx.strokeStyle='#ffbf7a';ctx.lineWidth=3*(1-p)+1;
    ctx.beginPath();ctx.arc(f.x,f.y,f.radius*(.3+.7*p),0,Math.PI*2);ctx.stroke();
  }else if(f.type==='repair'){
    ctx.strokeStyle='#b2ebbb';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(f.x,f.y);ctx.lineTo(f.x2,f.y2);ctx.stroke();circle(f.x2,f.y2,4,'#c7f0be');
  }else if(f.type==='cash'){
    text('+'+(f.amount||0),f.x,f.y-p*30,'#e9d98c',15);
  }else if(f.type==='spark'){
    let x=f.x+f.dx*p,y=f.y+f.dy*p+f.gravity*p*p;
    ctx.strokeStyle=p<.5?'#ffe8ad':'#f39a57';ctx.lineWidth=f.size*(1-p*.5);
    ctx.beginPath();ctx.moveTo(x-f.dx*.14,y-f.dy*.14);ctx.lineTo(x,y);ctx.stroke();
    circle(x,y,Math.max(.6,f.size*(1-p*.6)),'#ffdc91');
  }else if(f.type==='smoke'){
    let x=f.x+f.dx*p+Math.sin(p*5+f.seed)*4,y=f.y+f.dy*p,r=f.radius*(.35+p*.94);
    ctx.globalAlpha=Math.sin(Math.PI*p)*.4;
    circle(x,y,r,'#303a37');circle(x+r*.4,y-r*.3,r*.77,'#4c5551');circle(x-r*.35,y-r*.15,r*.64,'#6e6f62');
  }else if(f.type==='boom'){
    let r=f.radius||40,reach=r*(.17+p*.9);
    ctx.globalCompositeOperation='lighter';ctx.globalAlpha=remain*.6;
    circle(f.x,f.y,reach,'#f46c29');circle(f.x,f.y,reach*.59,'#ffb85a');circle(f.x,f.y,reach*.27,'#fff2bc');
    ctx.globalAlpha=remain*.9;ctx.strokeStyle='#ffd087';ctx.lineWidth=4*(1-p)+1;
    ctx.beginPath();ctx.arc(f.x,f.y,r*(.27+p*1.13),0,Math.PI*2);ctx.stroke();
  }else if(f.type==='hit'||f.type==='flash'){
    let r=f.type==='hit'?15:9;
    ctx.globalCompositeOperation='lighter';
    circle(f.x,f.y,r*(.3+p*.75),'#e9833e');circle(f.x,f.y,r*(.15+p*.38),'#fff0b2');
    ctx.strokeStyle='#ffe1a2';ctx.lineWidth=2*(1-p)+.5;ctx.beginPath();
    ctx.moveTo(f.x-r-p*r*.5,f.y);ctx.lineTo(f.x+r+p*r*.5,f.y);
    ctx.moveTo(f.x,f.y-r-p*r*.5);ctx.lineTo(f.x,f.y+r+p*r*.5);ctx.stroke();
  }else{
    circle(f.x,f.y,15*p+4,'#e69e4c');circle(f.x,f.y,8*p+2,'#ffe0a0');
  }
  ctx.restore();
}
function render(){
  let buildPreview=placement&&hoverActive&&!drag&&!commandBlocked()&&mouse.x>=0&&mouse.x<=WIDTH&&mouse.y>=0&&mouse.y<=HEIGHT?constructionPreview(placement,mouse):null,
      hoveredEntity=hoverEntity(),hoveredOre=hoverOre(hoveredEntity),postPreview=hoverPost(hoveredEntity,hoveredOre),
      hoveredRock=hoverRock(hoveredEntity,hoveredOre,postPreview);
  drawTerrain();drawCoordinateGrid();drawDepletedOreBeds();drawRocks();drawBattleScars();drawStrongholdMarker();
  for(let {ore:o,label,x,y} of oreLabelLayout()){
    circle(o.x,o.y,33,'#746544');
    for(let i=0,n=o.amount<=1500?1:o.amount<=4500?4:8;i<n;i++){
      let a=i*2.4;rect(o.x+Math.cos(a)*22-4,o.y+Math.sin(a)*21-5,9,12,i%2?'#c6b96d':'#e5d183');
    }
    text(label,x,y,'#e2d692',11);
  }
  for(let p of state.posts){
    let color=p.owner===0?'#9ddd8a':p.owner===1?'#df8a70':'#bfc39b';
    circle(p.x,p.y,27,'#233d2d');ctx.strokeStyle=color;ctx.lineWidth=2;
    ctx.beginPath();ctx.arc(p.x,p.y,28,0,Math.PI*2);ctx.stroke();
    rect(p.x-1,p.y-20,3,36,color);rect(p.x+2,p.y-20,19,12,color);
    if(p.progress>0){
      ctx.strokeStyle=p.side===0?'#a1ed84':'#f69872';ctx.lineWidth=4;
      ctx.beginPath();ctx.arc(p.x,p.y,33,-Math.PI/2,-Math.PI/2+Math.PI*2*p.progress/8);ctx.stroke();
    }
    text(postCaption(p),p.x-30,p.y+46,color,11);
  }
  drawConstructionRange(buildPreview);drawMiningOrders();drawEscortOrders();drawAttackOrders();drawQueuedAttackOrders();
  drawFactoryRallies();drawGuardAreas();drawPatrolOrders();drawQueuedOrders();drawSelectionRanges();
  drawPostCaptureRange(postPreview);drawHoverRange(hoveredEntity);drawCurrentOrderPaths();
  for(let e of state.entities){
    if(e.hp/e.max<.3){
      ctx.strokeStyle='#ed9870';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(e.x,e.y,e.r+8,0,Math.PI*2);ctx.stroke();
    }
    if(selection.has(e.id))drawSelectionFrame(e);
    defs[e.type].speed?(vehicleArtPreview?drawUnitPreview(e):drawUnit(e)):(vehicleArtPreview?drawBuildingPreview(e):drawBuilding(e));
    if(e.hp<e.max||selection.has(e.id)){
      let healthY=Math.max(0,e.y-e.r-12);
      rect(e.x-e.r-1,healthY-1,e.r*2+2,6,'#0b171c');rect(e.x-e.r,healthY,e.r*2,4,'#34433e');
      rect(e.x-e.r,healthY,e.r*2*Math.max(0,e.hp/e.max),4,e.hp/e.max<.3?'#ffbc78':e.team?'#e78f6a':'#a3db81');
    }
  }
  for(let s of state.shots)circle(s.x,s.y,3,'#ffedac');
  for(let f of state.fx)drawBattleEffect(f);
  drawConstructionGhost(buildPreview);
  if(drag&&dist(drag,mouse)>5){
    ctx.strokeStyle='#b5e997';ctx.fillStyle='#ade78b22';
    ctx.fillRect(drag.x,drag.y,mouse.x-drag.x,mouse.y-drag.y);ctx.strokeRect(drag.x,drag.y,mouse.x-drag.x,mouse.y-drag.y);
  }
  if(state.paused&&state.started&&!state.result){
    rect(0,0,WIDTH,HEIGHT,'#10231a88');text('战场已暂停',470,400,'#e5e8bd',32);
  }
  drawBattleAlert();drawHoverInspection(postPreview,hoveredEntity,hoveredOre,hoveredRock);
  drawConstructionBlocker(buildPreview);drawConstructionPanel(buildPreview);updateCoordinateAid();
}
